INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT159-S3-Q10$batch12$, 159, 3, 10, $batch12$Parallel Flaw$batch12$, $batch12$For years, Glenville had the highest apartment rents in the metropolitan region in which it is located. This year, Glenville has only the third highest apartment rents in the region. Therefore, it must cost less to rent an apartment in Glenville now than it used to.$batch12$, $batch12$Which one of the following arguments demonstrates most effectively by parallel reasoning that the argument above is flawed?$batch12$, $batch12$B$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT159-S3-Q10$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$Because Brenda’s kitten’s veterinary bills are lower than her puppy’s veterinary bills, the kitten must be healthier than the puppy.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$Because Brenda’s kitten was larger than her puppy a while ago but is now smaller than the puppy, the kitten must have shrunk.$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$Because Brenda’s kitten was born a week before her puppy was, Brenda must have gotten the kitten first.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$Because Brenda’s kitten eats less than her puppy does, the kitten is unlikely to become overweight.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$Because Brenda’s kitten has become more friendly toward her puppy recently, the puppy must have become more friendly toward the kitten.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Renting in Glenville costs less now than before.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Glenville went from the highest rents in the region to third highest.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$A drop in rank doesn't mean a drop in amount. Other towns' rents could have risen past Glenville's. The parallel must show a rank change misread as an absolute change, with an obviously false conclusion.$batch12$), (3, $batch12$Goal$batch12$, $batch12$A position changed relative to others, so the argument concludes the thing itself shrank.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This links bills to health. No change in rank over time.$batch12$), ($batch12$B$batch12$, $batch12$The kitten was bigger than the puppy and is now smaller, so "the kitten must have shrunk." The puppy just grew faster. The absurd conclusion exposes the same flaw.$batch12$), ($batch12$C$batch12$, $batch12$This is about birth order and acquisition order.$batch12$), ($batch12$D$batch12$, $batch12$This links eating less to weight risk.$batch12$), ($batch12$E$batch12$, $batch12$This assumes friendliness is mutual. No rank change.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT159-S3-Q10$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
